solution.solution.cpp:
const int* largerOf(const int* a, const int* b)
{
    if (a == nullptr || b == nullptr)
    {
        return nullptr;
    }
    return *b > *a ? b : a;
}

unitTests:
TEST("returns the pointer to the larger value") { int x{ 3 }, y{ 8 }; CHECK(largerOf(&x, &y) == &y); CHECK(largerOf(&y, &x) == &y); }
TEST("equal values give the first") { int x{ 5 }, y{ 5 }; CHECK(largerOf(&x, &y) == &x); }
TEST("null in, null out") { int x{ 1 }; CHECK(largerOf(nullptr, &x) == nullptr); CHECK(largerOf(&x, nullptr) == nullptr); CHECK(largerOf(nullptr, nullptr) == nullptr); }

